/bin/bash -lc "python - <<'PY'
import numpy as np
from collections import deque
f=np.load('source_pixels.npz')['rgb']
for k,im in enumerate(f):
 R,G,B=im.transpose(2,0,1)
 mask=(R>115)&(R>G*1.3)&(R>B*1.25)&(G<125)&(np.indices(R.shape)[0]>25)
 # comps
 seen=np.zeros(mask.shape,bool); comps=[]
 for y,x in zip(*np.where(mask & ~seen)):
  if seen[y,x]: continue
  q=[(y,x)];seen[y,x]=1; pts=[]
  for yy,xx in q:
   pts.append((yy,xx))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    ny,nx=yy+dy,xx+dx
    if 0<=ny<144 and 0<=nx<256 and mask[ny,nx] and not seen[ny,nx]: seen[ny,nx]=1;q.append((ny,nx))
  if len(pts)>8: comps.append(pts)
 cs=[]
 for p in comps:
  a=np.array(p); yy=a[:,0];xx=a[:,1]
  if yy.max()<115 and (xx.max()-xx.min())<25 and (yy.max()-yy.min())<25:
   cs.append((len(p),xx.mean(),yy.mean(),(xx.min(),yy.min(),xx.max(),yy.max())))
 if cs: print(k, sorted(cs,reverse=True)[:3])
PY"
